const buildSort = (params: any): object => {
    let sort: any = {};
    const sortBy = params.sortBy;
    const sortType = params.sortType;

    if (sortBy && sortType) {
        const order = sortType === "asc" || sortType === 1 ? 1 : -1;
        sort[sortBy] = order;
    } else {
        sort = { createdAt: -1 };
    }
    return sort;
};
